// Compute the readiness score
// Weighted score per account from usage growth, limit proximity, adoption breadth, engagement and buying signals; weights per segment live in a sheet the RevOps lead can tune.
return $input.all();

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "summary": { "type": "string" },
    "draft": { "type": "string", "description": "The message or document text this step produced, ready to send or review" },
    "subject": { "type": "string" },
    "confidence": { "type": "number" },
    "needs_human": { "type": "boolean" },
    "reasons": { "type": "array", "items": { "type": "string" } }
  },
  "required": ["summary", "confidence", "needs_human"]
}
